DROP TEMPORARY TABLE IF EXISTS virasat_migration_issues;
CREATE TEMPORARY TABLE virasat_migration_issues (issue VARCHAR(255) NOT NULL);
SET @check_enforcement_sql = IF(VERSION() LIKE '%MariaDB%', 'SELECT @@SESSION.check_constraint_checks INTO @checks_enabled', 'SET @checks_enabled=1');
PREPARE enforcement_stmt FROM @check_enforcement_sql;
EXECUTE enforcement_stmt;
DEALLOCATE PREPARE enforcement_stmt;
SET @enforced_sql = IF(VERSION() LIKE '%MariaDB%', 'SELECT 1', 'INSERT INTO virasat_migration_issues SELECT CONCAT(CHAR(67,72,69,67,75,32),CONSTRAINT_NAME) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND ENFORCED=CHAR(78,79)');
PREPARE enforced_stmt FROM @enforced_sql;
EXECUTE enforced_stmt;
DEALLOCATE PREPARE enforced_stmt;
SELECT * FROM virasat_migration_issues;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS - schema structure and core IDs verified' ELSE 'FAIL - do not mark migrations' END AS verification FROM virasat_migration_issues;
