INSERT INTO virasat_migration_issues SELECT 'Unsupported database version' WHERE IF(VERSION() LIKE '%MariaDB%', CAST(SUBSTRING_INDEX(REPLACE(VERSION(),'5.5.5-',''),'.',1) AS UNSIGNED)<10 OR (CAST(SUBSTRING_INDEX(REPLACE(VERSION(),'5.5.5-',''),'.',1) AS UNSIGNED)=10 AND CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(REPLACE(VERSION(),'5.5.5-',''),'.',2),'.',-1) AS UNSIGNED)<11), CAST(SUBSTRING_INDEX(REPLACE(VERSION(),'5.5.5-',''),'.',1) AS UNSIGNED)<8 OR (SUBSTRING_INDEX(REPLACE(VERSION(),'5.5.5-',''),'.',2)='8.0' AND CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(REPLACE(VERSION(),'5.5.5-',''),'.',3),'.',-1) AS UNSIGNED)<16));
